package com.casegen.ai.proposal.review;
import com.casegen.ai.proposal.domain.AiProposalType;
import com.casegen.modeling.domain.*;
import com.casegen.modeling.repository.UmlElementRepository;
import java.util.*;
import org.springframework.stereotype.Component;
@Component public class AiReviewSemanticValidator {
 private final AiReviewPayloadCanonicalizer canonicalizer;private final AiProposalDependencyGraph graph;private final UmlElementRepository elements;
 public AiReviewSemanticValidator(AiReviewPayloadCanonicalizer canonicalizer,AiProposalDependencyGraph graph,UmlElementRepository elements){this.canonicalizer=canonicalizer;this.graph=graph;this.elements=elements;}
 public ValidatedAiReview validate(GeneratedAiReview generated,AiUmlReviewSnapshot snapshot){if(generated.baseModelRevision()!=snapshot.modelRevision()||!generated.modelId().equals(snapshot.modelId())||!Objects.equals(generated.diagramId(),snapshot.diagram()==null?null:snapshot.diagram().id())||!Objects.equals(generated.baseDiagramRevision(),snapshot.diagram()==null?null:snapshot.diagram().revision()))throw error(AiReviewValidationErrorCode.REVIEW_CONTEXT_CHANGED,"review context changed");AiReviewResult review=generated.review();Map<String,AiReviewItem> items=new LinkedHashMap<>();review.items().forEach(i->items.put(i.clientRef(),i));Map<UUID,AiUmlReviewSnapshot.ClassifierEntry> classifiers=index(snapshot.classifiers(),AiUmlReviewSnapshot.ClassifierEntry::id);Map<UUID,AiUmlReviewSnapshot.PropertyEntry> properties=index(snapshot.properties(),AiUmlReviewSnapshot.PropertyEntry::id);Map<String,Set<String>> deps=new LinkedHashMap<>();Set<String> classifierNames=new HashSet<>();for(var c:snapshot.classifiers())classifierNames.add(key(c.packageId(),c.name()));Map<String,Set<String>> propertyNames=new HashMap<>();for(var p:snapshot.properties())propertyNames.computeIfAbsent(p.ownerClassifierId().toString(),k->new HashSet<>()).add(lower(p.name()));Set<UUID> updatedProperties=new HashSet<>();Set<String> relationKeys=new HashSet<>();for(var a:snapshot.associations())relationKeys.add(relation("A",a.firstEnd().classifierId().toString(),a.secondEnd().classifierId().toString()));Set<String> generalizationEdges=new HashSet<>();for(var g:snapshot.generalizations())generalizationEdges.add(g.specificClassifierId()+">"+g.generalClassifierId());Set<String> realizationKeys=new HashSet<>();for(var r:snapshot.realizations())realizationKeys.add(r.clientClassifierId()+">"+r.supplierClassifierId());
  for(AiReviewItem item:review.items()){Set<String> d=new LinkedHashSet<>(item.dependencies());d.addAll(derived(item.payload()));for(String ref:d){AiReviewItem target=items.get(ref);if(target==null)throw error(AiReviewValidationErrorCode.REFERENCED_ELEMENT_NOT_FOUND,"proposalRef does not exist");if(target.proposalType()!=AiReviewProposalType.ADD_CLASSIFIER&&usesAsElement(item.payload(),ref))throw error(AiReviewValidationErrorCode.INCOMPATIBLE_REFERENCE,"proposalRef must produce a classifier");}deps.put(item.clientRef(),d);validateItem(item,classifiers,properties,classifierNames,propertyNames,updatedProperties,relationKeys,generalizationEdges,realizationKeys,items,generated.modelId());}
  validateGeneralizationCycles(generalizationEdges);List<String> order=graph.topologicalOrder(review.items(),deps);Map<String,Integer> positions=new HashMap<>();for(int i=0;i<order.size();i++)positions.put(order.get(i),i+1);List<ValidatedAiReview.Item> validated=review.items().stream().sorted(Comparator.comparingInt(i->positions.get(i.clientRef()))).map(i->new ValidatedAiReview.Item(i.clientRef(),AiProposalType.valueOf(i.proposalType().name()),i.title(),i.rationale(),List.copyOf(deps.get(i.clientRef())),canonicalizer.canonicalize(i.payload()),positions.get(i.clientRef()))).toList();return new ValidatedAiReview(review.reviewTitle(),review.summary(),generated.baseModelRevision(),generated.baseDiagramRevision(),review.generatedByProvider(),generated.modelId(),generated.diagramId(),generated.sourceMessageId(),validated);}
 private void validateItem(AiReviewItem i,Map<UUID,AiUmlReviewSnapshot.ClassifierEntry> cs,Map<UUID,AiUmlReviewSnapshot.PropertyEntry> ps,Set<String> cn,Map<String,Set<String>> pn,Set<UUID> updated,Set<String> associations,Set<String> gens,Set<String> reals,Map<String,AiReviewItem> items,UUID modelId){switch(i.proposalType()){
  case ADD_CLASSIFIER->{var p=(ReviewAddClassifierPayload)i.payload();if(!cn.add(key(p.packageId(),p.name())))duplicate();if(p.kind()==ClassifierKind.INTERFACE&&Boolean.TRUE.equals(p.active()))invalid();}
  case UPDATE_CLASSIFIER->{var p=(ReviewUpdateClassifierPayload)i.payload();var old=require(cs,p.targetClassifierId(),modelId);if(old.kind()==ClassifierKind.INTERFACE&&Boolean.TRUE.equals(p.active()))invalid();String oldKey=key(old.packageId(),old.name()),newKey=key(p.packageId(),p.name());if(!oldKey.equals(newKey)&&!cn.add(newKey))duplicate();}
  case ADD_ATTRIBUTE->{var p=(ReviewAddAttributePayload)i.payload();String owner=logical(p.ownerRef(),cs,items);if(!pn.computeIfAbsent(owner,k->new HashSet<>()).add(lower(p.name())))duplicate();checkType(p.typeKind(),p.primitiveType(),p.typeClassifierRef(),cs,items);}
  case UPDATE_ATTRIBUTE->{var p=(ReviewUpdateAttributePayload)i.payload();var old=require(ps,p.targetPropertyId(),modelId);if(!updated.add(p.targetPropertyId()))duplicate();Set<String> names=pn.computeIfAbsent(old.ownerClassifierId().toString(),k->new HashSet<>());if(!lower(old.name()).equals(lower(p.name()))&&!names.add(lower(p.name())))duplicate();checkType(p.typeKind(),p.primitiveType(),p.typeClassifierRef(),cs,items);}
  case ADD_OPERATION->{var p=(ReviewAddOperationPayload)i.payload();logical(p.ownerRef(),cs,items);}
  case ADD_ASSOCIATION->{var p=(ReviewAddAssociationPayload)i.payload();String a=logical(p.firstEnd().classifierRef(),cs,items),b=logical(p.secondEnd().classifierRef(),cs,items);if(a.equals(b)||!associations.add(relation("A",a,b)))duplicate();if((p.firstEnd().aggregation()==AggregationKind.COMPOSITE&&p.firstEnd().upperBound()!=null&&p.firstEnd().upperBound()>1)||(p.secondEnd().aggregation()==AggregationKind.COMPOSITE&&p.secondEnd().upperBound()!=null&&p.secondEnd().upperBound()>1))invalid();}
  case ADD_GENERALIZATION->{var p=(ReviewAddGeneralizationPayload)i.payload();String a=logical(p.specificRef(),cs,items),b=logical(p.generalRef(),cs,items);ClassifierKind ak=kind(p.specificRef(),cs,items),bk=kind(p.generalRef(),cs,items);if(a.equals(b)||ak!=bk||!gens.add(a+">"+b))duplicate();}
  case ADD_REALIZATION->{var p=(ReviewAddRealizationPayload)i.payload();String a=logical(p.clientClassifierRef(),cs,items),b=logical(p.supplierRef(),cs,items);if(kind(p.clientClassifierRef(),cs,items)!=ClassifierKind.CLASS||kind(p.supplierRef(),cs,items)!=ClassifierKind.INTERFACE||!reals.add(a+">"+b))invalid();}}}
 private Set<String> derived(AiReviewPayload p){Set<String> r=new LinkedHashSet<>();refs(p).stream().map(ReviewElementRef::proposalRef).filter(Objects::nonNull).forEach(r::add);return r;}private boolean usesAsElement(AiReviewPayload p,String ref){return refs(p).stream().anyMatch(r->ref.equals(r.proposalRef()));}
 private List<ReviewElementRef> refs(AiReviewPayload p){List<ReviewElementRef> r=new ArrayList<>();if(p instanceof ReviewAddAttributePayload v){r.add(v.ownerRef());if(v.typeClassifierRef()!=null)r.add(v.typeClassifierRef());}else if(p instanceof ReviewAddOperationPayload v)r.add(v.ownerRef());else if(p instanceof ReviewAddAssociationPayload v){r.add(v.firstEnd().classifierRef());r.add(v.secondEnd().classifierRef());}else if(p instanceof ReviewAddGeneralizationPayload v){r.add(v.specificRef());r.add(v.generalRef());}else if(p instanceof ReviewAddRealizationPayload v){r.add(v.clientClassifierRef());r.add(v.supplierRef());}else if(p instanceof ReviewUpdateAttributePayload v&&v.typeClassifierRef()!=null)r.add(v.typeClassifierRef());return r;}
 private String logical(ReviewElementRef ref,Map<UUID,AiUmlReviewSnapshot.ClassifierEntry> cs,Map<String,AiReviewItem> items){if(ref.elementId()!=null){if(!cs.containsKey(ref.elementId()))missing(ref.elementId(),cs.values().stream().findFirst().map(x->x.id()).orElse(null));return ref.elementId().toString();}AiReviewItem item=items.get(ref.proposalRef());if(item==null)throw error(AiReviewValidationErrorCode.REFERENCED_ELEMENT_NOT_FOUND,"proposalRef missing");if(item.proposalType()!=AiReviewProposalType.ADD_CLASSIFIER)throw error(AiReviewValidationErrorCode.INCOMPATIBLE_REFERENCE,"reference is not a classifier");return "$"+ref.proposalRef();}
 private ClassifierKind kind(ReviewElementRef ref,Map<UUID,AiUmlReviewSnapshot.ClassifierEntry> cs,Map<String,AiReviewItem> items){if(ref.elementId()!=null)return require(cs,ref.elementId()).kind();return ((ReviewAddClassifierPayload)items.get(ref.proposalRef()).payload()).kind();}
 private void checkType(TypeKind k,PrimitiveType primitive,ReviewElementRef classifier,Map<UUID,AiUmlReviewSnapshot.ClassifierEntry> cs,Map<String,AiReviewItem> items){if(k==TypeKind.PRIMITIVE){if(primitive==null||classifier!=null)invalid();}else{if(primitive!=null||classifier==null)invalid();logical(classifier,cs,items);}}
 private void validateGeneralizationCycles(Set<String> edges){Map<String,List<String>> g=new HashMap<>();for(String e:edges){String[] p=e.split(">");g.computeIfAbsent(p[0],k->new ArrayList<>()).add(p[1]);}Set<String> visiting=new HashSet<>(),done=new HashSet<>();for(String n:g.keySet())dfs(n,g,visiting,done);}private void dfs(String n,Map<String,List<String>> g,Set<String> visiting,Set<String> done){if(done.contains(n))return;if(!visiting.add(n))throw error(AiReviewValidationErrorCode.DUPLICATE_ELEMENT,"generalization cycle");for(String x:g.getOrDefault(n,List.of()))dfs(x,g,visiting,done);visiting.remove(n);done.add(n);}
 private <T>T require(Map<UUID,T> values,UUID id){T v=values.get(id);if(v==null)throw error(AiReviewValidationErrorCode.REFERENCED_ELEMENT_NOT_FOUND,"referenced element not found");return v;}private <T>T require(Map<UUID,T> values,UUID id,UUID modelId){T v=values.get(id);if(v==null){var element=elements.findById(id);if(element.isPresent()&&!element.get().getModel().getId().equals(modelId))throw error(AiReviewValidationErrorCode.ELEMENT_OUTSIDE_MODEL,"referenced element belongs to another model");throw error(AiReviewValidationErrorCode.REFERENCED_ELEMENT_NOT_FOUND,"referenced element not found");}return v;}private void missing(UUID id,UUID ignored){var element=elements.findById(id);if(element.isPresent())throw error(AiReviewValidationErrorCode.ELEMENT_OUTSIDE_MODEL,"referenced classifier is not part of the reviewed model");throw error(AiReviewValidationErrorCode.REFERENCED_ELEMENT_NOT_FOUND,"referenced element not found");}private <T>Map<UUID,T> index(List<T> values,java.util.function.Function<T,UUID> id){Map<UUID,T> m=new HashMap<>();values.forEach(v->m.put(id.apply(v),v));return m;}private String relation(String t,String a,String b){return t+":"+(a.compareTo(b)<0?a+":"+b:b+":"+a);}private String key(UUID p,String n){return p+":"+lower(n);}private String lower(String s){return s.trim().toLowerCase(Locale.ROOT);}private void duplicate(){throw error(AiReviewValidationErrorCode.DUPLICATE_ELEMENT,"duplicate UML element");}private void invalid(){throw error(AiReviewValidationErrorCode.INVALID_PAYLOAD,"invalid review payload");}private AiReviewValidationException error(AiReviewValidationErrorCode c,String m){return new AiReviewValidationException(c,m);}}
